/**
 * Nigerian Draughts Game Logic & Rules
 * Implements 10x10 board coordinate system, conversions to SCAN 3.1 engine format,
 * and a fully accurate legal move generator with flying kings, free-choice captures,
 * and delayed-removal (ghost pieces) rules.
 */

export interface Move {
  from: number;     // 1-50 Nigerian sq
  to: number;       // 1-50 Nigerian sq
  caps: number[];   // list of captured squares in sequence
  /** Landing squares of each jump in order (last === to). Present on
   *  capture moves generated by this engine; lets the UI accept
   *  physical-board style square-by-square jump clicking. Optional so
   *  historical moves stored without it (saved games, old puzzles) stay
   *  valid. */
  path?: number[];
}

export type Piece = "w" | "W" | "b" | "B" | null;

export interface Board {
  [sq: number]: Piece;
}

// ── Coordinate Conversions ──────────────────────────────────────────────────

/**
 * Convert a Nigerian square number (1 to 50) to [row, col] coordinates (0 to 9)
 * Row 0 is the top, row 9 is the bottom.
 * Active squares are always dark squares where (row + col) % 2 == 0.
 */
export function ngSqToRc(sq: number): [number, number] {
  const z = sq - 1;
  const row = Math.floor(z / 5);
  const col = (z % 5) * 2 + (row % 2 === 0 ? 0 : 1);
  return [row, col];
}

/**
 * Convert [row, col] coordinates to Nigerian square number (1 to 50),
 * or return null if off-board or not a dark active square.
 */
export function ngRcToSq(row: number, col: number): number | null {
  if (row < 0 || row >= 10 || col < 0 || col >= 10) return null;
  if ((row + col) % 2 !== 0) return null;
  return row * 5 + Math.floor(col / 2) + 1;
}

/**
 * Converts a Nigerian square number (1-50) to SCAN engine square number (1-50).
 * This is a self-inverse bijection.
 */
export function convertSq(sq: number): number {
  const rb = Math.floor((sq - 1) / 5) * 5 + 1;
  return 2 * rb + 4 - sq;
}

/**
 * Convert a move string (e.g. "35-30" or "20x29x38") between Nigerian and SCAN numbering.
 * Since the square mapping is self-inverse, this function converts both ways.
 */
export function convertMoveStr(s: string): string {
  return s.replace(/\d+/g, (m) => String(convertSq(parseInt(m, 10))));
}

// ── Helper Utilities ────────────────────────────────────────────────────────

export function getCol(pc: Piece): "W" | "B" | null {
  if (!pc) return null;
  return pc === "w" || pc === "W" ? "W" : "B";
}

export function isKing(pc: Piece): boolean {
  return pc === "W" || pc === "B";
}

function getOppColor(c: "W" | "B"): "W" | "B" {
  return c === "W" ? "B" : "W";
}

// Directions for movement (4 diagonals)
const DIRS: [number, number][] = [
  [-1, -1],
  [-1, 1],
  [1, -1],
  [1, 1],
];

// Forward directions for quiet moves
const FWD = {
  W: [
    [-1, -1],
    [-1, 1],
  ], // White moves up
  B: [
    [1, -1],
    [1, 1],
  ], // Black moves down
};

const PROMO = {
  W: 0,  // White promotes at row 0 (squares 1-5)
  B: 9,  // Black promotes at row 9 (squares 46-50)
};

// ── Move Generation ──────────────────────────────────────────────────────────

/**
 * Generate quiet moves for a standard man.
 */
function getManQuiets(sq: number, board: Board, color: "W" | "B"): Move[] {
  const [r, c] = ngSqToRc(sq);
  const moves: Move[] = [];
  const dirs = FWD[color];

  for (const [dr, dc] of dirs) {
    const t = ngRcToSq(r + dr, c + dc);
    if (t && !board[t]) {
      moves.push({ from: sq, to: t, caps: [] });
    }
  }
  return moves;
}

/**
 * Recursive generator for standard man captures.
 * Uses delayed removal: captured pieces stay on board during multi-jump as walls.
 */
function mcRec(
  start: number,
  cur: number,
  bd: Board,
  caps: number[],
  res: Move[],
  seen: Set<string>,
  enemy: "W" | "B",
  path: number[] = []
) {
  const [r, c] = ngSqToRc(cur);
  let found = false;

  for (const [dr, dc] of DIRS) {
    const mid = ngRcToSq(r + dr, c + dc);
    const land = ngRcToSq(r + 2 * dr, c + 2 * dc);

    if (mid === null || land === null) continue;

    const mp = bd[mid];
    if (!mp || getCol(mp) !== enemy) continue;
    if (caps.includes(mid)) continue; // cannot jump same piece twice

    // Landing spot must be empty, or can be the start square (delayed removal)
    if (bd[land] && land !== start) continue;

    found = true;
    mcRec(start, land, bd, [...caps, mid], res, seen, enemy, [...path, land]);
  }

  // Only terminal jumps are legal in Nigerian/International Draughts (no prefixes)
  if (caps.length > 0 && !found) {
    // Dedup key
    const sortedCaps = [...caps].sort().join(",");
    const key = `${start}->${cur}:[${sortedCaps}]`;
    if (!seen.has(key)) {
      seen.add(key);
      res.push({ from: start, to: cur, caps, path });
    }
  }
}

/**
 * Generate quiet moves for a king.
 * Slides any number of empty squares.
 */
function getKingQuiets(sq: number, board: Board): Move[] {
  const [r, c] = ngSqToRc(sq);
  const moves: Move[] = [];

  for (const [dr, dc] of DIRS) {
    let nr = r + dr;
    let nc = c + dc;
    while (true) {
      const t = ngRcToSq(nr, nc);
      if (t === null || board[t]) break;
      moves.push({ from: sq, to: t, caps: [] });
      nr += dr;
      nc += dc;
    }
  }
  return moves;
}

/**
 * Recursive generator for king captures.
 * King slides to enemy, jumps over it, and can land on any square behind it.
 * Delayed removal: captured pieces stay as blockers during the jump chain.
 */
function kcRec(
  start: number,
  cur: number,
  bd: Board,
  caps: number[],
  res: Move[],
  seen: Set<string>,
  enemy: "W" | "B",
  path: number[] = []
) {
  const [r, c] = ngSqToRc(cur);
  let found = false;

  for (const [dr, dc] of DIRS) {
    let nr = r + dr;
    let nc = c + dc;
    let esq: number | null = null;

    // Slide to find the first piece along this diagonal
    while (true) {
      const sq2 = ngRcToSq(nr, nc);
      if (sq2 === null) break;
      // The mover vacated its starting square. Captured pieces still block
      // rays until the complete chain ends, but the origin must not.
      const p2 = sq2 === start ? null : bd[sq2];
      if (p2) {
        if (getCol(p2) === enemy && !caps.includes(sq2)) {
          esq = sq2;
        }
        break; // block ray
      }
      nr += dr;
      nc += dc;
    }

    if (esq === null) continue;

    const [er, ec] = ngSqToRc(esq);
    let lr = er + dr;
    let lc = ec + dc;

    // Slide behind the enemy to find valid landing squares
    while (true) {
      const land = ngRcToSq(lr, lc);
      if (land === null) break;
      if (bd[land] && land !== start) break; // block ray

      found = true;
      kcRec(start, land, bd, [...caps, esq], res, seen, enemy, [...path, land]);
      lr += dr;
      lc += dc;
    }
  }

  if (caps.length > 0 && !found) {
    const sortedCaps = [...caps].sort().join(",");
    const key = `${start}->${cur}:[${sortedCaps}]`;
    if (!seen.has(key)) {
      seen.add(key);
      res.push({ from: start, to: cur, caps, path });
    }
  }
}

/**
 * Generate all legally available moves for the active player.
 * Enforces capture obligation.
 */
export function generateLegalMoves(board: Board, turn: "W" | "B"): Move[] {
  const caps: Move[] = [];
  const quiets: Move[] = [];

  const playerPieces: number[] = [];
  for (let sq = 1; sq <= 50; sq++) {
    if (board[sq] && getCol(board[sq]) === turn) {
      playerPieces.push(sq);
    }
  }

  const enemy = getOppColor(turn);

  // 1. First find all possible captures for any of the player's pieces
  for (const sq of playerPieces) {
    const pc = board[sq]!;
    if (isKing(pc)) {
      const res: Move[] = [];
      const seen = new Set<string>();
      kcRec(sq, sq, board, [], res, seen, enemy);
      caps.push(...res);
    } else {
      const res: Move[] = [];
      const seen = new Set<string>();
      mcRec(sq, sq, board, [], res, seen, enemy);
      caps.push(...res);
    }
  }

  // 2. If captures exist, capture is mandatory
  if (caps.length > 0) {
    return caps;
  }

  // 3. Otherwise, generate quiet moves for all pieces
  for (const sq of playerPieces) {
    const pc = board[sq]!;
    if (isKing(pc)) {
      quiets.push(...getKingQuiets(sq, board));
    } else {
      quiets.push(...getManQuiets(sq, board, turn));
    }
  }

  return quiets;
}

/**
 * Apply a move to the board and return the new board state.
 * Also handles promotion to King if landing on the promotion row at the END of the move.
 */
export function applyMove(board: Board, mv: Move): { board: Board; promoted: boolean } {
  const newBoard = { ...board };
  const pc = newBoard[mv.from];
  if (!pc) throw new Error(`No piece at starting square ${mv.from}`);

  // Clear starting square
  newBoard[mv.from] = null;

  // Clear all captured squares (delayed removal completes now)
  for (const cap of mv.caps) {
    newBoard[cap] = null;
  }

  // Check promotion
  const [r] = ngSqToRc(mv.to);
  const color = getCol(pc)!;
  let promoted = false;
  let finalPc = pc;

  if (!isKing(pc) && r === PROMO[color]) {
    finalPc = color === "W" ? "W" : "B";
    promoted = true;
  }

  newBoard[mv.to] = finalPc;

  return { board: newBoard, promoted };
}

/**
 * Converts a Move to the same "from-to" / "fromxtoxcap1xcap2" notation the
 * SCAN engine itself emits (see nd_upgraded/move.cpp: to_hub()), using this
 * app's own Nigerian square numbering (NOT engine/SCAN numbering -- caller
 * should apply convertSq() first if comparing directly against a string the
 * engine returned, since the engine speaks in its own square numbering).
 */
export function moveToNotationString(mv: Move): string {
  let s = `${mv.from}${mv.caps.length > 0 ? "x" : "-"}${mv.to}`;
  for (const cap of mv.caps) s += `x${cap}`;
  return s;
}

/**
 * Parses a "from-to" or "fromxtoxcap1xcap2..." move string (this app's own
 * Nigerian numbering, or SCAN numbering if the caller converts first) into
 * its from/to/caps parts. Returns null if the string can't be parsed.
 */
export function parseNotationString(s: string): { from: number; to: number; caps: number[] } | null {
  const trimmed = s.trim();
  // Consume the entire token; parseInt must not accept a legal prefix of junk.
  if (!/^\d{1,2}-\d{1,2}$/.test(trimmed) && !/^\d{1,2}(?:x\d{1,2})+$/.test(trimmed)) return null;
  const parts = trimmed.split(/[-x]/).map(Number);
  if (parts.some((square) => !Number.isInteger(square) || square < 1 || square > 50)) return null;
  const [from, to, ...caps] = parts;
  return { from, to, caps };
}

/**
 * Converts a hub/SCAN-numbered move string (as returned by the engine's
 * "done move=..." / "info pv=..." lines) into this app's Nigerian numbering,
 * so it can be compared directly against a Move object from gameLogic.
 */
export function hubMoveStringToNigerian(s: string): { from: number; to: number; caps: number[] } | null {
  const parsed = parseNotationString(s);
  if (!parsed) return null;
  return {
    from: convertSq(parsed.from),
    to: convertSq(parsed.to),
    caps: parsed.caps.map(convertSq),
  };
}

/**
 * True if two moves land on the same square from the same square and
 * capture the same set of pieces (order-independent) -- i.e. they are the
 * same move, regardless of how the capture chain was notated.
 */
export function movesAreEquivalent(
  a: { from: number; to: number; caps: number[] } | null | undefined,
  b: { from: number; to: number; caps: number[] } | null | undefined
): boolean {
  if (!a || !b) return false;
  if (typeof a.from !== "number" || typeof a.to !== "number") return false;
  if (typeof b.from !== "number" || typeof b.to !== "number") return false;
  if (a.from !== b.from || a.to !== b.to) return false;
  const aCaps = Array.isArray(a.caps) ? a.caps : [];
  const bCaps = Array.isArray(b.caps) ? b.caps : [];
  if (aCaps.length !== bCaps.length) return false;
  const sa = [...aCaps].sort((x, y) => x - y);
  const sb = [...bCaps].sort((x, y) => x - y);
  return sa.every((v, i) => v === sb[i]);
}

/** A move's clickable landing sequence (falls back to [to] for quiet moves
 *  and for historical capture moves stored without a path). */
export function movePath(m: Move): number[] {
  return m.path && m.path.length > 0 ? m.path : [m.to];
}

/**
 * Which squares should light up as tap targets for a selected piece, given
 * the jump-path squares already clicked (`walked`)? Every candidate move
 * whose path starts with `walked` contributes its NEXT landing square, and
 * its FINAL square (so the classic one-tap-to-the-end gesture keeps
 * working alongside square-by-square jumping).
 */
export function captureClickTargets(candidates: Move[], walked: number[]): Set<number> {
  const targets = new Set<number>();
  for (const m of candidates) {
    const path = movePath(m);
    if (walked.length > path.length) continue;
    if (!walked.every((sqr, i) => path[i] === sqr)) continue;
    if (walked.length < path.length) targets.add(path[walked.length]); // next hop
    targets.add(m.to); // one-tap completion
  }
  return targets;
}

/**
 * Resolves a tap on `clicked` for a selected piece, supporting BOTH input
 * styles draughts players use:
 *   - one tap on the final landing square plays the whole capture line;
 *   - tapping the landing squares one jump at a time (physical-board
 *     style) walks the line, applying the move on its last square.
 *
 * `candidates` = every legal move from the selected square; `walked` = the
 * intermediate landings already clicked this selection.
 */
export function resolveCaptureClick(
  candidates: Move[],
  walked: number[],
  clicked: number
): { kind: "apply"; move: Move } | { kind: "extend"; walked: number[] } | { kind: "miss" } {
  const survivors = candidates.filter((m) => {
    const path = movePath(m);
    return walked.length <= path.length && walked.every((sqr, i) => path[i] === sqr);
  });
  if (survivors.length === 0) return { kind: "miss" };

  const nextWalked = [...walked, clicked];

  // Exact completion: clicking the LAST square of a fully-walked path.
  const exact = survivors.find((m) => {
    const path = movePath(m);
    return path.length === nextWalked.length && path[path.length - 1] === clicked;
  });
  if (exact) return { kind: "apply", move: exact };

  // Lines continuing through the clicked landing square.
  const continuing = survivors.filter((m) => movePath(m)[walked.length] === clicked && movePath(m).length > nextWalked.length);

  // "Capture as long as possible": when exactly ONE line runs through the
  // tapped landing, the rest of the chain is FORCED -- play the whole
  // capture immediately instead of making the player tap every hop.
  if (continuing.length === 1) return { kind: "apply", move: continuing[0] };

  // Several lines diverge after this landing: keep walking to disambiguate.
  if (continuing.length > 1) return { kind: "extend", walked: nextWalked };

  // One-tap (or early) completion on a final square further down a line.
  const finisher = survivors.find((m) => m.to === clicked);
  if (finisher) return { kind: "apply", move: finisher };

  return { kind: "miss" };
}

// ============================================================
// Puzzle line verification -- the single source of truth for
// "does this trap actually follow the game rules?"
// Used by the admin Trap Creator (before saving), by the server
// (rejecting any illegal line at the API), and conceptually by the
// player (which replays the same verified moves).
// ============================================================

export interface PuzzleLineStep {
  from: number;
  to: number;
  caps?: number[];
  role?: "solver" | "reply";
  text?: string;
}

export interface PuzzleLineReport {
  ok: boolean;
  /** Human-readable reason naming the exact failing step when !ok. */
  error?: string;
  stepsVerified: number;
  /** True when, after the final solver move, the defender has NO legal
   *  reply (win by capture-out or blocking) -- the strongest kind of trap. */
  endsWithWin: boolean;
  finalBoard: Board;
  finalTurn: "W" | "B";
}

/**
 * Replays `steps` from `startBoard` under the FULL rules of the game:
 * turns alternate, every step must be a currently-legal move (captures
 * obligatory but free-choice of length per rule 2.9, flying kings, delayed
 * removal, promotion -- everything generateLegalMoves/applyMove enforce),
 * the line must start and end with the solver, and it must STOP the
 * moment the game is won (a "reply" for a side with no legal moves is
 * impossible in real play).
 */
export function verifyPuzzleLine(
  startBoard: Board,
  firstMover: "W" | "B",
  steps: PuzzleLineStep[]
): PuzzleLineReport {
  const fail = (error: string, stepsVerified: number, board: Board, turn: "W" | "B"): PuzzleLineReport =>
    ({ ok: false, error, stepsVerified, endsWithWin: false, finalBoard: board, finalTurn: turn });

  let board: Board = { ...startBoard };
  let turn: "W" | "B" = firstMover;

  if (!steps || steps.length === 0) return fail("The solution has no moves.", 0, board, turn);

  for (let i = 0; i < steps.length; i++) {
    const step = steps[i];
    const expectedRole: "solver" | "reply" = i % 2 === 0 ? "solver" : "reply";
    const role = step.role === "reply" ? "reply" : step.role === "solver" ? "solver" : expectedRole;
    const stepName = step.text || `${step.from}${step.caps && step.caps.length ? "x" : "-"}${step.to}`;

    if (role !== expectedRole) {
      return fail(
        `Step ${i + 1} (${stepName}) is marked as the ${role}'s move, but by turn order it must be the ${expectedRole}'s -- in a real game the sides always alternate.`,
        i, board, turn
      );
    }

    const legal = generateLegalMoves(board, turn);
    if (legal.length === 0) {
      return fail(
        `The game is already WON before step ${i + 1}: ${turn === "W" ? "White" : "Black"} has no legal move. End the recorded line at the previous move -- the rules don't allow play to continue past a win.`,
        i, board, turn
      );
    }

    let mv: Move | undefined;
    if (step.caps && step.caps.length > 0) {
      const wanted = [...step.caps].sort((a, b) => a - b).join(",");
      mv = legal.find(
        (m) => m.from === step.from && m.to === step.to &&
          [...m.caps].sort((a, b) => a - b).join(",") === wanted
      );
    } else {
      mv = legal.find((m) => m.from === step.from && m.to === step.to && m.caps.length === 0)
        ?? legal.find((m) => m.from === step.from && m.to === step.to);
    }

    if (!mv) {
      const mandatory = legal.some((m) => m.caps.length > 0);
      return fail(
        `Step ${i + 1} (${stepName}) is not a legal move for ${turn === "W" ? "White" : "Black"} in this position` +
          (mandatory ? " -- a capture is obligatory here (any legal capture length is allowed under rule 2.9's free choice), and this exact from/to/caps doesn't match one." : "."),
        i, board, turn
      );
    }

    board = applyMove(board, mv).board;
    turn = turn === "W" ? "B" : "W";
  }

  if (steps.length % 2 === 0) {
    return fail(
      "The line ends on the defender's reply -- a puzzle must end on the solver's move. Remove the trailing reply or record the solver's answer to it.",
      steps.length, board, turn
    );
  }

  const endsWithWin = generateLegalMoves(board, turn).length === 0;
  return { ok: true, stepsVerified: steps.length, endsWithWin, finalBoard: board, finalTurn: turn };
}

/**
 * Parses a pasted PDN-style move list into an ordered array of Move objects,
 * validating each move against the actual legal-move generator so illegal or
 * garbled input is rejected rather than silently desyncing the board.
 *
 * Expected format: optional move numbers ("1.", "2.") followed by alternating
 * White/Black moves in this app's own square notation, e.g.:
 *   "1. 32-28 19-23 2. 37-32 23x32 3. 28x19 14x23"
 * (Space, newline, or move-number-separated -- move numbers are ignored.)
 *
 * Throws a descriptive Error naming the exact token that failed, instead of
 * failing silently, so the UI can show the user precisely what to fix.
 */
export function parsePdnMoveList(pdnText: string): Move[] {
  const tokens = pdnText
    .split(/\s+/)
    .map((t) => t.trim())
    .filter((t) => t.length > 0 && !/^\d+\.+$/.test(t) && t !== "*"); // drop "1." move numbers and PGN-style "*" terminators

  const moves: Move[] = [];
  let board = createInitialBoard();
  let turn: "W" | "B" = "W";

  for (let idx = 0; idx < tokens.length; idx++) {
    const token = tokens[idx];
    const parsed = parseNotationString(token);
    if (!parsed) {
      throw new Error(`Move #${idx + 1} ("${token}") isn't valid notation. Use "from-to" or "fromxtoxcap" (e.g. 32-28 or 19x28x37).`);
    }

    const legalMoves = generateLegalMoves(board, turn);
    const match = legalMoves.find((mv) => movesAreEquivalent(mv, parsed));
    if (!match) {
      throw new Error(
        `Move #${idx + 1} ("${token}") is not legal for ${turn === "W" ? "White" : "Black"} in this position. ` +
          `Double-check the square numbers and that captures are complete.`
      );
    }

    moves.push(match);
    board = applyMove(board, match).board;
    turn = turn === "W" ? "B" : "W";
  }

  return moves;
}
/**
 * Set up initial 10x10 Nigerian Draughts starting board.
 * White pieces ('w') occupy squares 31 to 50 (rows 6-9).
 * Black pieces ('b') occupy squares 1 to 20 (rows 0-3).
 */
export function createInitialBoard(): Board {
  const board: Board = {};
  for (let sq = 1; sq <= 50; sq++) {
    if (sq >= 1 && sq <= 20) {
      board[sq] = "b";
    } else if (sq >= 31 && sq <= 50) {
      board[sq] = "w";
    } else {
      board[sq] = null;
    }
  }
  return board;
}

/**
 * Convert a move to HUB format (SCAN notation).
 */
export function moveToHubString(move: Move): string {
  return convertMoveStr(moveToNotationString(move));
}

/**
 * Converts the current board state to a SCAN FEN string (51 characters).
 * Turn indicator + 50 squares (w, W, b, B, or e for empty).
 */
export function boardToScanFen(board: Board, turn: "W" | "B"): string {
  const chars: string[] = [turn];
  for (let scanSq = 1; scanSq <= 50; scanSq++) {
    const ngSq = convertSq(scanSq);
    let pc = board[ngSq];
    // Auto-promote men on the promotion edge to keep the position strictly valid for Scan engine
    if (pc === "w" && ngSq >= 1 && ngSq <= 5) pc = "W";
    if (pc === "b" && ngSq >= 46 && ngSq <= 50) pc = "B";
    chars.push(pc ? pc : "e");
  }
  return chars.join("");
}

/**
 * Parse a SCAN FEN string back into a Board state.
 */
export function scanFenToBoard(fen: string): { board: Board; turn: "W" | "B" } {
  const turn = fen[0] as "W" | "B";
  const board: Board = {};
  for (let scanSq = 1; scanSq <= 50; scanSq++) {
    const ngSq = convertSq(scanSq);
    const char = fen[scanSq];
    board[ngSq] = char === "e" ? null : (char as Piece);
  }
  return { board, turn };
}

interface PieceCounts {
  whiteMen: number;
  whiteKings: number;
  blackMen: number;
  blackKings: number;
}

function countPieces(board: Board): PieceCounts {
  const counts: PieceCounts = { whiteMen: 0, whiteKings: 0, blackMen: 0, blackKings: 0 };
  for (let sq = 1; sq <= 50; sq++) {
    const pc = board[sq];
    if (!pc) continue;
    const white = getCol(pc) === "W";
    const king = isKing(pc);
    if (white && king) counts.whiteKings++;
    else if (white) counts.whiteMen++;
    else if (king) counts.blackKings++;
    else counts.blackMen++;
  }
  return counts;
}

function countsEqual(a: PieceCounts, b: PieceCounts): boolean {
  return a.whiteMen === b.whiteMen && a.whiteKings === b.whiteKings && a.blackMen === b.blackMen && a.blackKings === b.blackKings;
}

/**
 * Which material-insufficiency category (if any) the position falls into,
 * per Kenny's spec:
 *  - "three": one side has a lone king (1 king, 0 men) and the OTHER side
 *    has exactly 3 pieces total, including at least one king (so: 3 kings,
 *    2 kings + 1 man, or 1 king + 2 men) -> draw after 16 moves EACH side.
 *  - "two": one side has a lone king and the other side has 2 pieces or
 *    fewer, including at least one king (1 king, 2 kings, or 1 king + 1
 *    man) -> draw after 5 moves EACH side.
 * Returns null if neither applies.
 */
function materialCategory(c: PieceCounts): "three" | "two" | null {
  const whiteLoneKing = c.whiteKings === 1 && c.whiteMen === 0;
  const blackLoneKing = c.blackKings === 1 && c.blackMen === 0;
  if (!whiteLoneKing && !blackLoneKing) return null;

  // If BOTH sides happen to be a lone king (1 king vs 1 king), that's the
  // "two or fewer" category from either side's perspective -- fall through
  // naturally since the counts below handle it the same either way.
  const strongCount = whiteLoneKing ? c.blackMen + c.blackKings : c.whiteMen + c.whiteKings;
  const strongHasKing = whiteLoneKing ? c.blackKings >= 1 : c.whiteKings >= 1;

  if (!strongHasKing) return null; // spec requires the stronger side to include at least one king
  if (strongCount === 3) return "three";
  if (strongCount <= 2) return "two"; // covers 1 or 2, per spec ("2 pieces or less")
  return null;
}

export interface GameEndResult {
  isOver: boolean;
  winner: "W" | "B" | null; // null when isOver && it's a draw
  isDraw: boolean;
  reason: string;
}

const NO_END: GameEndResult = { isOver: false, winner: null, isDraw: false, reason: "" };

/**
 * The single, authoritative game-end check -- covers every rule Kenny
 * specified, in priority order:
 *   1. No legal moves for the side to move -> the OTHER side wins immediately.
 *      (This is the fundamental win condition and always takes priority
 *      over any draw rule.)
 *   2. Threefold repetition: the same (board, side-to-move) position
 *      occurring 3 times across the game's history -> draw.
 *   3. 25 consecutive moves BY EACH SIDE (50 plies) that are all king moves
 *      with no captures -> draw. Any man-move or capture resets the streak.
 *   4. Lone king vs exactly 3 pieces (incl. >=1 king): draw once that exact
 *      material split has persisted for 16 moves BY EACH SIDE (32 plies)
 *      with no capture or promotion changing it.
 *   5. Lone king vs <=2 pieces (incl. >=1 king): same idea, 5 moves BY EACH
 *      SIDE (10 plies).
 *
 * Takes the FULL move history so it can correctly evaluate repetition and
 * the move-counted rules, which single-position checks structurally cannot
 * do. This is called from BOTH the client (for instant local feedback in
 * AI/analysis games) and the server (as the authoritative check for PvP,
 * which previously had no such check at all).
 */
export function checkGameEnd(history: Move[], initialBoard: Board = createInitialBoard(), initialTurn: "W" | "B" = "W"): GameEndResult {
  // Reconstruct every board position in the game, 0..history.length.
  const boards: Board[] = [{ ...initialBoard }];
  for (let i = 0; i < history.length; i++) {
    boards.push(applyMove(boards[i], history[i]).board);
  }
  const finalBoard = boards[boards.length - 1];
  const sideToMove: "W" | "B" = history.length % 2 === 0 ? initialTurn : getOppColor(initialTurn);

  // 1. No legal moves -> opponent wins.
  if (generateLegalMoves(finalBoard, sideToMove).length === 0) {
    const winner: "W" | "B" = sideToMove === "W" ? "B" : "W";
    return { isOver: true, winner, isDraw: false, reason: "No legal moves left" };
  }

  // 2. Threefold repetition (same board + same side to move, 3 times).
  {
    let repeats = 1;
    for (let i = boards.length - 1 - 2; i >= 0; i -= 2) {
      // Same parity of ply => same side to move as the final position.
      if (boardsEqual(boards[i], finalBoard)) {
        repeats++;
        if (repeats >= 3) {
          return { isOver: true, winner: null, isDraw: true, reason: "Threefold repetition" };
        }
      }
    }
  }

  // 3. 25 consecutive king-only, capture-free moves BY EACH SIDE (50 plies).
  {
    let streak = 0;
    for (let i = history.length - 1; i >= 0; i--) {
      const mv = history[i];
      const moverBoard = boards[i];
      const movedPiece = moverBoard[mv.from];
      const wasKingMove = !!movedPiece && isKing(movedPiece);
      const wasCapture = mv.caps.length > 0;
      if (wasKingMove && !wasCapture) {
        streak++;
      } else {
        break;
      }
    }
    if (streak >= 50) {
      return { isOver: true, winner: null, isDraw: true, reason: "25 consecutive king moves by each side with no capture" };
    }
  }

  // 4 & 5. Material-insufficiency rules. Find how long the CURRENT category
  // has held continuously -- walk backward until the piece composition
  // changes (a capture or a promotion), which is the only thing that can
  // alter which category applies.
  {
    const currentCounts = countPieces(finalBoard);
    const category = materialCategory(currentCounts);
    if (category) {
      let pliesInCategory = 0;
      for (let i = boards.length - 1; i > 0; i--) {
        if (countsEqual(countPieces(boards[i - 1]), currentCounts)) {
          pliesInCategory++;
        } else {
          break;
        }
      }
      const threshold = category === "three" ? 32 : 10; // 16 or 5 moves EACH side
      if (pliesInCategory >= threshold) {
        const moves = category === "three" ? 16 : 5;
        return {
          isOver: true,
          winner: null,
          isDraw: true,
          reason: category === "three"
            ? `Lone king vs 3 pieces (incl. a king): no progress in ${moves} moves by each side`
            : `Lone king vs 2 or fewer pieces (incl. a king): no progress in ${moves} moves by each side`,
        };
      }
    }
  }

  return NO_END;
}

function boardsEqual(a: Board, b: Board): boolean {
  for (let sq = 1; sq <= 50; sq++) {
    if ((a[sq] ?? null) !== (b[sq] ?? null)) return false;
  }
  return true;
}

